import{_ as t,o,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-09-14","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-09-14","date":"2021-09-14T00:00:00.000Z","updated":"2021-09-15T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","监控","决策"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-14.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-14.md","lastUpdated":1780459816000}'),p={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-09-14.md"};function r(s,e,n,a,_,h){return o(),i("div",null,[...e[0]||(e[0]=[l("<p>Ceph Orchestrator 会议于2021年9月14日举行，会议主要讨论了以下议题：</p><ol><li><p><strong>Topo LVM 更新与动态配置</strong>：讨论了将外部团队作为Rook存储提供商的可能性，但对方不感兴趣。团队计划继续研究Topo LVM的动态配置，特别是针对raw设备的配置。Ron Joseph等人正在进行原型设计，以更好地理解集成方式。</p></li><li><p><strong>自动缩放与平衡模块</strong>：讨论了自动缩放和平衡模块的配置选项，建议在升级过程中可能需要禁用平衡器以避免潜在问题，并建议将其作为可配置选项。</p></li><li><p><strong>健康警告与监控恢复</strong>：讨论了在失去所有监控集群时的恢复路径，建议增加健康警告机制。现有手动步骤包括从OSDs重建监控，以及通过复制数据来恢复监控。</p></li><li><p><strong>KCI环境中的主机维护问题</strong>：讨论了KCI环境中主机维护模式的问题，初步判断问题可能与KCLI无关，需要进一步在管理器中进行调查。</p></li><li><p><strong>Prometheus绑定问题</strong>：讨论了Prometheus绑定到所有接口的问题，建议调整拉取请求以避免覆盖端口，并探索使用不同命令进行活性探测。</p></li><li><p><strong>Rook与Ceph版本兼容性</strong>：讨论了Joseph的NFS池更改，计划在Ceph 7版本中合并，以确保稳定性和兼容性。</p></li><li><p><strong>ISCSI配置工具集成</strong>：讨论了将ISCSI配置工具集成到Ceph CLI中的可能性，以便更方便地进行配置。</p></li></ol><p>会议决定：</p><ul><li>继续推进Topo LVM的动态配置研究和原型设计。</li><li>在升级过程中考虑禁用平衡器，并将其作为可配置选项。</li><li>增加健康警告机制，并完善监控恢复路径。</li><li>调查并解决KCI环境中的主机维护问题。</li><li>调整Prometheus绑定问题的拉取请求，并探索新的活性探测方法。</li><li>确保 NFS 池更改与 Ceph 7 版本的兼容性。</li><li>探索将 ISCSI 配置工具集成到 Ceph CLI 中的可能性。</li></ul><p>后续行动计划包括：</p><ul><li>继续Topo LVM的原型设计和动态配置研究。</li><li>实施并测试禁用平衡器的配置选项。</li><li>开发和测试健康警告机制及监控恢复路径。</li><li>深入调查KCI环境中的主机维护问题。</li><li>调整Prometheus绑定问题的拉取请求，并实施新的活性探测方法。</li><li>确保 NFS 池更改与 Ceph 7 版本的兼容性，并进行相关测试。</li><li>与 ISCSI 专家合作，探索并实现 ISCSI 配置工具的集成。</li></ul><p>会议涵盖了多个关键议题，包括存储提供商合作、动态配置、健康监控、版本兼容性等。团队将继续推进各项议题的研究和实施，确保 Ceph 和 Rook 的稳定性和功能性。</p>",7)])])}const c=t(p,[["render",r]]);export{g as __pageData,c as default};
